/*
 * p9share_conf.h -- what p9share.conf(5) says.
 *
 * The file is read by the parser in p9share_conf.c, which was generated by hbnf from
 * grammars/p9share.hbnf (see HACKING); the build does not need hbnf.  The blocks are
 * checked as they are read (conf.c), so what is in a struct p9share_conf is valid.
 */
#ifndef P9SHARE_CONF_H
#define P9SHARE_CONF_H

#include <stddef.h>

/* export "NAME" { directory DIR  host HOST } */
struct p9share_export {
    char   *name, *directory, *host;
    size_t  line;                       /* the line of the file the block starts on */
};

/* mount "NAME" { user USER  at MOUNTPOINT } */
struct p9share_mount {
    char   *name, *user, *at;
    size_t  line;
};

struct p9share_conf {
    struct p9share_export *exports;
    size_t                 nexports;
    struct p9share_mount  *mounts;
    size_t                 nmounts;
};

void p9share_conf_init(struct p9share_conf *c);
void p9share_conf_free(struct p9share_conf *c);

/* Read the file into *c (after p9share_conf_init).  Returns 0, or -1 after having printed every
 * error as "file:line: message" on standard error; the blocks that were fine are in *c anyway.
 * A file that does not exist is an error here: ask p9share_file_exists first when it may be absent. */
int p9share_conf_parse(const char *path, struct p9share_conf *c);

/* Used by the parser's actions: take the block (which becomes the conf's) after checking it.  NULL
 * when it was taken, else the message; the block is then the caller's to free. */
const char *p9share_conf_add_export(struct p9share_conf *c, const struct p9share_export *e);
const char *p9share_conf_add_mount(struct p9share_conf *c, const struct p9share_mount *m);

/* What may go where: a name is letters, digits and . _ - (not first: . _ -); a user is a login
 * name; a host is a name as ssh knows it (not starting with -); a path is absolute and has only
 * letters, digits and . _ + @ - / (so it can be put in an option string and a command line as it
 * is).  Each returns 1 if valid. */
int p9share_valid_name(const char *s);
int p9share_valid_user(const char *s);
int p9share_valid_host(const char *s);
int p9share_valid_path(const char *s);

#endif /* P9SHARE_CONF_H */
